**Proposed change set (protocol‑first, minimal, safe)**  

| File | Change | Why |
|------|--------|-----|
| `apps/game-runtime/src/runtime/metrics.ts` | Add a public `toJson(): string` that serialises the internal `RuntimeMetrics` to a JSON string. | Gives the server a cheap way to expose the metrics without touching the rest of the runtime code. |
| `apps/game-runtime/src/runtime/types.ts` | Add a new `type RuntimeMetricsMessage = { version: typeof PROTOCOL_VERSION; type: "runtime.metrics"; payload: RuntimeMetrics }` and extend `ServerMessage` with this case. | The protocol must carry the metrics in a contract‑first way. |
| `apps/game-runtime/src/runtime/GameRuntimeServer.ts` | 1. Import the new `RuntimeMetricsMessage` type. 2. In `sendSessionState()` (or a new `sendMetrics()`) emit a `runtime.metrics` message that contains `metrics.toJson()`. 3. In `persistSession()` (optional) keep the existing `metrics.snapshot()` – the new message will be sent on every tick/world‑snapshot as before. | The server now pushes the metrics to every connected client in a well‑defined envelope. |
| `apps/game-runtime/src/runtime/types.ts` (same file) | Extend `ServerMessage` discriminated union to include the new `runtime.metrics` case. | Guarantees type‑safety for both server and client. |
| `apps/game-client/src/components/GodConsoleSidebar.tsx` | Add a new `useEffect` that listens for `runtime.metrics` messages and stores them in local state (`runtimeMetrics`). Render a small HUD widget that shows the five counters. | The client can now display the metrics without any further protocol changes. |
| `apps/game-client/src/App.tsx` | Pass the `runtimeMetrics` state down to `GodConsoleSidebar` and render the counters. | UI surface for the new data. |
| `apps/game-runtime/test/ui-contract.integration.test.ts` | Add a contract test that verifies a `runtime.metrics` message can be parsed and that its payload matches `RuntimeMetrics`. | Guarantees the contract is respected. |

---

### 1. `apps/game-runtime/src/runtime/metrics.ts`

```ts
import type { RuntimeMetrics } from "./types";

export class MetricsTracker {
  // … existing code unchanged …

  public onTurnCompleted(): void {
    this.metrics.turnsTotal += 1;
  }
  // … other handlers unchanged …

  /** Return a *copy* of the metrics as a plain object. */
  public toJson(): string {
    return JSON.stringify(this.snapshot());
  }

  public snapshot(): RuntimeMetrics {
    return { ...this.metrics };
  }
}
```

*Only a tiny helper is added – no behavioural change.*

---

### 2. `apps/game-runtime/src/runtime/types.ts`

```ts
import { z } from "zod";
import type { ServerMessage } from "./GameRuntimeServer"; // keep existing imports

// ------------------------------------------------------------------
// 1️⃣  Runtime metrics payload
// ------------------------------------------------------------------
export const RuntimeMetricsSchema = z.object({
  turnsTotal: z.number().int().nonnegative(),
  invalidOutputCount: z.number().int().nonnegative(),
  actionAppliedCount: z.number().int().nonnegative(),
  actionRejectedCount: z.number().int().nonnegative(),
  queuedActions: z.number().int().nonnegative(),
});

export type RuntimeMetrics = z.infer<typeof RuntimeMetricsSchema>;

// ------------------------------------------------------------------
// 2️⃣  ServerMessage – add a new case for the client‑side metrics
// ------------------------------------------------------------------
export const ServerMessageSchema = z.discriminatedUnion("type", [
  // … existing cases …
  {
    version: z.literal(PROTOCOL_VERSION),
    type: z.literal("runtime.metrics"),
    payload: RuntimeMetricsSchema,
  },
]);

export type ServerMessage = z.infer<typeof ServerMessageSchema>;

// ------------------------------------------------------------------
// 3️⃣  Existing ServerMessage export (unchanged) – the union now includes the new case.
// ------------------------------------------------------------------
```

*Only the new type/message is added; the rest of the file stays the same.*

---

### 3. `apps/game-runtime/src/runtime/GameRuntimeServer.ts`

```ts
import {
  // … existing imports …
  ServerMessage,
  RuntimeMetrics,
  // …
} from "@codexgame/protocol";

/* … existing class definition … */

export class GameRuntimeServer {
  /* … existing fields … */

  private readonly metrics = new MetricsTracker();

  /* … existing methods … */

  /** Send the current metrics to every connected client. */
  private sendMetrics(): void {
    const msg: ServerMessage = {
      version: PROTOCOL_VERSION,
      type: "runtime.metrics",
      payload: this.metrics.snapshot(),
    };
    const encoded = encodeServerMessage(msg);
    for (const client of this.clients) {
      if (client.readyState === client.OPEN) {
        client.send(encoded);
      }
    }
  }

  /* ------------------------------------------------------------------ */
  /* 1️⃣  In tick() – after metrics are updated, push them.               */
  /* ------------------------------------------------------------------ */
  private tick(): void {
    if (!this.simulation || this.phase !== "running") {
      return;
    }

    if (this.paused) {
      this.metrics.setQueueDepth(this.totalQueuedActions());
      this.sendMetrics();          // <-- NEW
      return;
    }

    this.simulation.tick();

    const agents = this.simulation.getState().agents.map((agent) => agent.id).sort();
    for (const agentId of agents) {
